import { createFileRoute, Navigate } from '@tanstack/react-router';
import { useEffect, useMemo } from 'react';

import {
  getStartPathByStep,
  normalizeStartFunnelSessionStorage,
  readStartFunnelSession
} from '@/routes/_authenticated/start/-funnelStorage';

export const Route = createFileRoute('/_authenticated/start/')({
  component: RouteComponent
});

function RouteComponent() {
  const funnelSession = useMemo(() => readStartFunnelSession(), []);

  useEffect(() => {
    normalizeStartFunnelSessionStorage();
  }, []);

  if (!funnelSession) {
    return <Navigate to="/start/template" replace />;
  }

  const step =
    funnelSession.step === 'generate' &&
    !funnelSession.context?.exportedProductId
      ? 'settings'
      : funnelSession.step;

  return <Navigate to={getStartPathByStep(step)} replace />;
}
